    "patches": "[id=\"root\"] {\n  box-sizing: border-box;\n  background: #fff;\n  border: 1px solid #ccd5df;\n  box-shadow: 0 1px #fff, 0 3px 12px #17202d1f;\n}\n\nbody[data-ds-dark-theme] [id=\"root\"] {\n  background: #10151d;\n  border-color: #232c3a;\n  box-shadow: 0 1px #0a0e15, 0 3px 12px #00000080;\n}\n\n* {\n  border-radius: 3px !important;\n}\n\n[data-pane=\"sidebar\"] {\n  color: var(--dsw-alias-label-primary);\n}\n\n[role=\"tooltip\"] {\n  background: var(--dsw-alias-tooltip-bg);\n  color: var(--dsw-alias-tooltip-fg);\n}\n\n[role=\"dialog\"], [role=\"dialog\"] [class*=\"navCell\"]:not([aria-current=\"true\"]) {\n  color: var(--dsw-alias-label-primary);\n}\n\nbutton[role=\"tab\"], button[role=\"tab\"]:hover, button[role=\"tab\"]:active, button[role=\"tab\"]:disabled, button[role=\"tab\"]:hover:not(:disabled), button[role=\"tab\"]:active:not(:disabled) {\n  box-shadow: none;\n  text-shadow: none;\n  color: var(--dsw-alias-label-primary);\n  filter: none;\n  opacity: 1;\n  background-color: #0000;\n  background-image: none;\n  border: 0;\n  transform: none;\n}\n\n::-webkit-scrollbar {\n  width: 10px;\n  height: 10px;\n}\n\n::-webkit-scrollbar-track {\n  background: none;\n}\n\n::-webkit-scrollbar-thumb {\n  background: var(--dsw-alias-border-l3);\n  background-clip: content-box;\n  border: 2px solid #0000;\n  border-radius: 5px;\n}\n\n::-webkit-scrollbar-thumb:hover {\n  background: var(--dsw-alias-border-l4);\n  background-clip: content-box;\n}\n\n.nudqwq_tradingTitlebar {\n  z-index: 1000000;\n  background: var(--dsh-trd-titlebar-bg);\n  border-bottom: 1px solid var(--dsh-trd-border);\n  height: 34px;\n  color: var(--dsh-trd-text);\n  font: 600 13px/34px var(--dsw-font-family);\n  user-select: none;\n  align-items: center;\n  gap: 8px;\n  padding: 0 8px;\n  display: flex;\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n}\n\n.nudqwq_tradingTitlebarIcon {\n  background: var(--dsh-trd-brand);\n  border-radius: 5px;\n  justify-content: center;\n  align-items: center;\n  width: 20px;\n  height: 20px;\n  display: inline-flex;\n  box-shadow: inset 0 1px #ffffff40;\n}\n\n.nudqwq_tradingTitlebarIcon svg {\n  width: 14px;\n  height: 14px;\n  display: block;\n}\n\n.nudqwq_tradingTitlebarTitle {\n  color: var(--dsh-trd-text);\n  letter-spacing: .02em;\n  white-space: nowrap;\n}\n\n.nudqwq_tradingTitlebarChips {\n  align-items: center;\n  gap: 14px;\n  margin-left: auto;\n  display: inline-flex;\n  overflow: hidden;\n}\n\n.nudqwq_tradingTitlebarChip {\n  font: 500 12px/1 var(--ds-font-family-code);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n  align-items: baseline;\n  gap: 5px;\n  display: inline-flex;\n}\n\n.nudqwq_tradingTitlebarChipName {\n  color: var(--dsh-trd-dim);\n}\n\n.nudqwq_tradingTitlebarChipVal {\n  color: var(--dsh-trd-text);\n  font-weight: 600;\n}\n\n.nudqwq_tradingTitlebarChipChg[data-trend=\"up\"] {\n  color: var(--dsh-trd-up);\n}\n\n.nudqwq_tradingTitlebarChipChg[data-trend=\"down\"] {\n  color: var(--dsh-trd-down);\n}\n\n.nudqwq_tradingTitlebarChipChg:not([data-trend]) {\n  color: var(--dsh-trd-flat);\n}\n\n.nudqwq_tradingTitlebarBtn {\n  text-align: center;\n  width: 26px;\n  color: var(--dsh-trd-dim);\n  border-radius: 4px;\n  display: inline-block;\n}\n\n.nudqwq_tradingTitlebarBtn:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsh-trd-text);\n}\n\n.nudqwq_tradingTape {\n  z-index: 999999;\n  background: var(--dsh-trd-tape-bg);\n  border-bottom: 1px solid var(--dsh-trd-border);\n  user-select: none;\n  height: 30px;\n  position: fixed;\n  top: 34px;\n  left: 0;\n  right: 0;\n  overflow: hidden;\n}\n\n.nudqwq_tradingTapeTrack {\n  white-space: nowrap;\n  will-change: transform;\n  align-items: center;\n  height: 100%;\n  animation: 60s linear infinite nudqwq_tradingTapeMove;\n  display: inline-flex;\n}\n\n.nudqwq_tradingTape:hover .nudqwq_tradingTapeTrack {\n  animation-play-state: paused;\n}\n\n.nudqwq_tradingTapeItem {\n  border-right: 1px solid var(--dsw-alias-border-l2);\n  height: 100%;\n  font: 500 12px/30px var(--ds-font-family-code);\n  font-variant-numeric: tabular-nums;\n  align-items: baseline;\n  gap: 6px;\n  padding: 0 16px;\n  display: inline-flex;\n}\n\n.nudqwq_tradingTapeName {\n  color: var(--dsh-trd-dim);\n  white-space: nowrap;\n}\n\n.nudqwq_tradingTapePrice {\n  color: var(--dsh-trd-text);\n  font-weight: 600;\n}\n\n.nudqwq_tradingTapeChg[data-trend=\"up\"] {\n  color: var(--dsh-trd-up);\n  font-weight: 600;\n}\n\n.nudqwq_tradingTapeChg[data-trend=\"down\"] {\n  color: var(--dsh-trd-down);\n  font-weight: 600;\n}\n\n.nudqwq_tradingTapeChg:not([data-trend]) {\n  color: var(--dsh-trd-flat);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .nudqwq_tradingTapeTrack {\n    animation: none;\n  }\n}\n\n.nudqwq_tradingStatusbar {\n  z-index: 1000000;\n  background: var(--dsh-trd-statusbar-bg);\n  border-top: 1px solid var(--dsh-trd-border);\n  height: 26px;\n  color: var(--dsh-trd-dim);\n  font: 500 12px/26px var(--ds-font-family-code);\n  font-variant-numeric: tabular-nums;\n  user-select: none;\n  white-space: nowrap;\n  align-items: center;\n  gap: 14px;\n  padding: 0 10px;\n  display: flex;\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  right: 0;\n}\n\n.nudqwq_tradingStatusbarGroup {\n  align-items: center;\n  gap: 12px;\n  display: inline-flex;\n}\n\n.nudqwq_tradingStatusbarSpacer {\n  flex: 1;\n}\n\n.nudqwq_tradingStatusbarCell {\n  color: var(--dsh-trd-dim);\n  align-items: baseline;\n  gap: 4px;\n  display: inline-flex;\n}\n\n.nudqwq_tradingStatusbarCell[data-phase=\"trading\"] {\n  color: var(--dsh-trd-up);\n}\n\n.nudqwq_tradingStatusbarCell[data-phase=\"lunch\"], .nudqwq_tradingStatusbarCell[data-phase=\"pre\"] {\n  color: var(--dsh-trd-warn);\n}\n\n.nudqwq_tradingStatusbarCell[data-trend=\"up\"] {\n  color: var(--dsh-trd-up);\n}\n\n.nudqwq_tradingStatusbarCell[data-trend=\"down\"] {\n  color: var(--dsh-trd-down);\n}\n\n.nudqwq_tradingStatusbarLbLabel {\n  color: var(--dsh-trd-brand);\n  font-weight: 600;\n}\n\n@keyframes nudqwq_tradingTapeMove {\n  0% {\n    transform: translate(0);\n  }\n\n  to {\n    transform: translate(-50%);\n  }\n}\n"
